parameters.jsCode:
const dow = new Date().getDay();
const day = new Date().getDate();
return $input.all().filter(item => {
  const p = (item.json.periodicite || '').toLowerCase();
  if (p === 'daily' || p === 'quotidien')    return true;
  if (p === 'weekly' || p === 'hebdomadaire') return dow === 1;
  if (p === 'monthly' || p === 'mensuel')      return day === 1;
  return false;
});

const abonne = $('Loop Over Abonnés').item.json;
const articles = $input.all().map(i => i.json);

const dateStr = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' });
const HEADER = '#1a1a2e';
const ACCENT = '#457b9d';
const FOND = '#f8f9fa';
const TEXTE = '#333333';
const SEC = '#666666';
const TAG_BG = '#e8f4f8';
const TAG_TXT = '#2c6e8a';

function badge(mot) {
  return '<span style="display:inline-block;background:' + TAG_BG + ';color:' + TAG_TXT + ';font-size:11px;padding:2px 8px;border-radius:12px;margin:2px 3px 2px 0;">' + mot + '</span>';
}

function carteArticle(a) {
  const lien = (a.url_source && a.url_source !== 'none' && a.url_source !== 'aucune')
    ? '<a href="' + a.url_source + '" style="display:inline-block;margin-top:10px;color:' + ACCENT + ';font-size:12px;text-decoration:none;border:1px solid ' + ACCENT + ';padding:3px 10px;border-radius:4px;">Read Source &rarr;</a>'
    : '';
  let mots = [];
  try { mots = Array.isArray(a.mots_cles) ? a.mots_cles : JSON.parse(a.mots_cles || '[]'); } catch(e) {}
  return '<div style="background:#fff;border:1px solid #e0e0e0;border-radius:8px;padding:16px 20px;margin-bottom:12px;">'
    + '<p style="margin:0 0 6px 0;font-size:16px;font-weight:bold;color:' + TEXTE + ';">' + (a.titre_article || '(Untitled)') + '</p>'
    + '<p style="margin:0 0 10px 0;font-size:14px;color:' + SEC + ';line-height:1.5;">' + (a.resume_court || '') + '</p>'
    + (mots.length ? '<div style="margin-bottom:8px;">' + mots.map(badge).join('') + '</div>' : '')
    + lien + '</div>';
}

const parTheme = {};
for (const a of articles) {
  const t = a.theme_principal || 'General';
  if (!parTheme[t]) parTheme[t] = [];
  parTheme[t].push(a);
}

let contenu = '';
for (const [theme, arts] of Object.entries(parTheme)) {
  contenu += '<table width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:24px;">'
    + '<tr><td style="border-left:4px solid ' + ACCENT + ';padding-left:12px;">'
    + '<p style="margin:0;font-size:18px;font-weight:bold;color:' + HEADER + ';">' + theme + '</p>'
    + '<p style="margin:2px 0 0 0;font-size:12px;color:' + SEC + ';">' + arts.length + ' article' + (arts.length > 1 ? 's' : '') + '</p>'
    + '</td></tr><tr><td style="padding-top:12px;">' + arts.map(carteArticle).join('') + '</td></tr></table>';
}

const pRaw = (abonne.periodicite || '').toLowerCase();
const periodiciteLabel = (pRaw === 'weekly' || pRaw === 'hebdomadaire') ? 'weekly' : (pRaw === 'monthly' || pRaw === 'mensuel') ? 'monthly' : 'daily';
const periodicitesujet = (pRaw === 'weekly' || pRaw === 'hebdomadaire') ? 'Weekly' : (pRaw === 'monthly' || pRaw === 'mensuel') ? 'Monthly' : 'Daily';

const html = '<!DOCTYPE html><html><body style="margin:0;padding:0;background:' + FOND + ';font-family:Arial,Helvetica,sans-serif;">'
  + '<table width="100%" cellpadding="0" cellspacing="0"><tr><td align="center" style="padding:24px 16px;">'
  + '<table width="640" cellpadding="0" cellspacing="0" style="max-width:640px;width:100%;">'
  + '<tr><td style="background:' + HEADER + ';border-radius:10px 10px 0 0;padding:28px 32px;">'
  + '<p style="margin:0;font-size:13px;color:#aaaacc;text-transform:uppercase;letter-spacing:2px;">Your Curated Briefing</p>'
  + '<p style="margin:6px 0 4px 0;font-size:26px;font-weight:bold;color:#ffffff;">Hello ' + abonne.prenom + ' 👋</p>'
  + '<p style="margin:0;font-size:14px;color:#aaaacc;">' + dateStr + ' &bull; ' + articles.length + ' article' + (articles.length > 1 ? 's' : '') + ' curated for you</p>'
  + '</td></tr>'
  + '<tr><td style="background:' + FOND + ';padding:24px 32px;">' + contenu + '</td></tr>'
  + '<tr><td style="background:#eeeeee;padding:12px 32px;border-top:1px solid #dddddd;">'
  + '<p style="margin:0;font-size:12px;color:' + SEC + ';">You are receiving this digest <strong>' + periodiciteLabel + '</strong>.</p>'
  + '</td></tr>'
  + '<tr><td style="background:' + HEADER + ';border-radius:0 0 10px 10px;padding:20px 32px;">'
  + '<p style="margin:0;font-size:12px;color:#aaaacc;">To customize your topics, change frequency, or unsubscribe,<br>reply to this email or write to <strong style="color:#ffffff;">bot@example.com</strong> in plain English.<br><em>Examples: "switch to weekly" &bull; "add AI topic" &bull; "unsubscribe"</em></p>'
  + '</td></tr>'
  + '</table></td></tr></table></body></html>';

const sujet = '📰 News Digest (' + periodicitesujet + ') - ' + dateStr + ' - ' + articles.length + ' article' + (articles.length > 1 ? 's' : '');

return [{ json: { sujet, html, abonne_id: abonne.id, article_ids: JSON.stringify(articles.map(a => a.id)) } }];

